var H = load("res://tests/helpers/sm11e_m2b_scen.gd")
H.setup({"cp": {"1": 0, "2": 0}, "place": {"U_MEGANOBZ_A": [26.0, 37.0]}})
PhaseManager.transition_to_phase(8)
return int(GameState.get_current_phase())

var H = load("res://tests/helpers/sm11e_m2b_scen.gd")
var d = H.dice("to_hit")
return d.get("rolls_raw", []).size()

var H = load("res://tests/helpers/sm11e_m2b_scen.gd")
var ws = []
var hurt = 0
for m in H.unit("U_MEGANOBZ_A").models:
	var w = int(m.get("current_wounds", 3)) if m.get("alive", true) else 0
	ws.append(w)
	if w < 3:
		hurt += 1
print("[sm11e master-forged] meganobz wounds: ", ws)
return H.log_count("(AP -2)") >= 1 and not ws.has(2) and hurt >= 1
